package com.mybank.pbac.controller;
import com.mybank.pbac.model.GuardrailType; import com.mybank.pbac.service.PolicyImportService; import com.mybank.pbac.service.PolicyImportService.ImportResult; import java.util.List; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/policies") public class PolicyImportController{private final PolicyImportService importer;public PolicyImportController(PolicyImportService i){importer=i;}@PostMapping("/import")public ImportResult importPolicies(@RequestParam("files")List<MultipartFile> files,@RequestParam Long industryId,@RequestParam GuardrailType guardrailType,@RequestParam(required=false)String guardrailSubtype){return importer.importFiles(files,industryId,guardrailType,guardrailSubtype);}}
